<?php require __DIR__.'/config.php';$user=require_login();method_is('POST');$id=(int)($_POST['order_id']??0);$reference=trim((string)($_POST['reference']??''));if($id<1||$reference===''||mb_strlen($reference)>190)json_out(['error'=>'Enter a valid payment reference.'],422);$s=$pdo->prepare('SELECT o.id,o.customer_id,p.id payment_id,p.method,p.status FROM orders o JOIN payments p ON p.order_id=o.id WHERE o.id=? AND o.customer_id=? ORDER BY p.id DESC LIMIT 1');$s->execute([$id,$user['id']]);$row=$s->fetch();if(!$row||!in_array($row['method'],['GCash','Maya'],true))json_out(['error'=>'Online payment record not found.'],404);$path=null;if(isset($_FILES['screenshot'])&&$_FILES['screenshot']['error']!==UPLOAD_ERR_NO_FILE){$f=$_FILES['screenshot'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>5*1024*1024)json_out(['error'=>'Screenshot must be an image under 5 MB.'],422);$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext||!getimagesize($f['tmp_name']))json_out(['error'=>'Upload a JPG, PNG, or WebP image.'],422);$dir=dirname(__DIR__).'/assets/payments/uploads';if(!is_dir($dir)&&!mkdir($dir,0750,true))json_out(['error'=>'Unable to store screenshot.'],500);$file='payment-'.$id.'-'.bin2hex(random_bytes(8)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$file))json_out(['error'=>'Unable to store screenshot.'],500);$path='assets/payments/uploads/'.$file;}$s=$pdo->prepare("UPDATE payments SET gateway_reference=?,payment_screenshot=COALESCE(?,payment_screenshot),status='Pending Verification',verified_by=NULL,verified_at=NULL WHERE id=?");$s->execute([$reference,$path,$row['payment_id']]);json_out(['ok'=>true]);?>